const search=document.getElementById('review-search'),group=document.getElementById('review-group'),cards=[...document.querySelectorAll('.review-case')];function filter(){const q=search.value.trim().toLowerCase();let n=0;for(const c of cards){c.hidden=!(group.value==='all'||c.dataset.group===group.value)||!c.dataset.search.includes(q);if(!c.hidden)n++;}document.getElementById('review-count').textContent=n+' models';}search.addEventListener('input',filter);group.addEventListener('change',filter);
